from collections import deque,defaultdict

def comps(mat, val, r0=0,r1=None,c0=0,c1=None):
 r1=r1 or len(mat); c1=c1 or len(mat[0]); seen=set(); out=[]
 for r in range(r0,r1):
  for c in range(c0,c1):
   if mat[r][c]!=val or (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c)); pts=[]
   while q:
    x,y=q.pop();pts.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     p=(x+dx,y+dy)
     if r0<=p[0]<r1 and c0<=p[1]<c1 and p not in seen and mat[p[0]][p[1]]==val: seen.add(p);q.append(p)
   out.append(pts)
 return out

def normshape(pts):
